-- ---------------------------------------------------------------------
-- Activity log (written by triggers only)
-- ---------------------------------------------------------------------
create table public.activity_log (
  id         bigint generated always as identity primary key,
  project_id uuid not null references public.projects (id) on delete cascade,
  task_id    uuid references public.tasks (id) on delete set null,
  actor_id   uuid references public.profiles (id) on delete set null,
  action     text not null,            -- e.g. task.created, task.updated, task.deleted
  changes    jsonb not null default '{}'::jsonb,  -- { field: [old, new] }
  created_at timestamptz not null default now()
);
create index activity_project_idx on public.activity_log (project_id, created_at desc);
create index activity_task_idx on public.activity_log (task_id, created_at desc);

create or replace function app.log_task_activity()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  diff jsonb := '{}'::jsonb;
  col  text;
  o    jsonb;
  n    jsonb;
begin
  if tg_op = 'INSERT' then
    insert into public.activity_log (project_id, task_id, actor_id, action, changes)
    values (new.project_id, new.id, auth.uid(), 'task.created', jsonb_build_object('title', jsonb_build_array(null, new.title)));
    return new;
  elsif tg_op = 'DELETE' then
    -- Skip when the whole project is being deleted (cascade).
    if not exists (select 1 from public.projects where id = old.project_id) then
      return old;
    end if;
    insert into public.activity_log (project_id, task_id, actor_id, action, changes)
    values (old.project_id, null, auth.uid(), 'task.deleted', jsonb_build_object('title', jsonb_build_array(old.title, null)));
    return old;
  end if;

  o := to_jsonb(old);
  n := to_jsonb(new);
  foreach col in array array['title','description','status_id','priority','start_date','due_date','progress','group_id','custom_values'] loop
    if o->col is distinct from n->col then
      diff := diff || jsonb_build_object(col, jsonb_build_array(o->col, n->col));
    end if;
  end loop;
  if diff <> '{}'::jsonb then
    insert into public.activity_log (project_id, task_id, actor_id, action, changes)
    values (new.project_id, new.id, auth.uid(), 'task.updated', diff);
  end if;
  return new;
end;
$$;
create trigger tasks_activity after insert or update or delete on public.tasks
  for each row execute function app.log_task_activity();

-- Mark completed_at when the status becomes a "done" label.
create or replace function app.task_completion()
returns trigger
language plpgsql
set search_path = ''
as $$
declare done boolean;
begin
  select s.is_done into done from public.status_labels s where s.id = new.status_id;
  if coalesce(done, false) then
    new.completed_at := coalesce(new.completed_at, now());
    new.progress := 100;
  else
    new.completed_at := null;
  end if;
  return new;
end;
$$;
create trigger tasks_completion before insert or update of status_id on public.tasks
  for each row execute function app.task_completion();

-- ---------------------------------------------------------------------
-- Client share links (read-only Gantt). Public access goes through a
-- SECURITY DEFINER function added in phase 3 — never through the tables.
-- ---------------------------------------------------------------------
create table public.share_links (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references public.projects (id) on delete cascade,
  token          text not null unique default encode(extensions.gen_random_bytes(24), 'hex'),
  label          text check (char_length(label) <= 120),
  hide_owners    boolean not null default true,
  hide_internal_notes boolean not null default true,
  expires_at     timestamptz default now() + interval '90 days',
  revoked_at     timestamptz,
  last_viewed_at timestamptz,
  created_by     uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at     timestamptz not null default now()
);
create index share_links_project_idx on public.share_links (project_id);

-- ---------------------------------------------------------------------
-- New project → creator becomes member, default status labels
-- ---------------------------------------------------------------------
create or replace function app.handle_new_project()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if auth.uid() is not null then
    insert into public.project_members (project_id, user_id, added_by)
    values (new.id, auth.uid(), auth.uid()) on conflict do nothing;
  end if;
  insert into public.status_labels (project_id, name, color, position, is_done) values
    (new.id, 'Not started',   '#94a3b8', 0, false),
    (new.id, 'Working on it', '#f59e0b', 1, false),
    (new.id, 'Stuck',         '#ef4444', 2, false),
    (new.id, 'Done',          '#22c55e', 3, true);
  return new;
end;
$$;
create trigger projects_after_insert after insert on public.projects
  for each row execute function app.handle_new_project();

-- =====================================================================
-- Row Level Security
-- =====================================================================
alter table public.clients              enable row level security;
alter table public.projects             enable row level security;
alter table public.project_members      enable row level security;
alter table public.status_labels        enable row level security;
alter table public.project_columns      enable row level security;
alter table public.groups               enable row level security;
alter table public.tasks                enable row level security;
alter table public.task_assignees       enable row level security;
alter table public.task_dependencies    enable row level security;
alter table public.task_checklist_items enable row level security;
alter table public.milestones           enable row level security;
alter table public.comments             enable row level security;
alter table public.attachments          enable row level security;
alter table public.activity_log         enable row level security;
alter table public.share_links          enable row level security;

-- Clients: any active user can read (name/logo shown on projects); managers+ write; admin deletes.
create policy "clients: active read" on public.clients
  for select to authenticated using (app.is_active());
create policy "clients: manager insert" on public.clients
  for insert to authenticated with check (app.is_manager_or_above());
create policy "clients: manager update" on public.clients
  for update to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());
create policy "clients: admin delete" on public.clients
  for delete to authenticated using (app.is_admin());

-- Projects
create policy "projects: read if visible" on public.projects
  for select to authenticated using (app.can_view_project(id));
create policy "projects: manager insert" on public.projects
  for insert to authenticated with check (app.is_manager_or_above());
create policy "projects: manager update" on public.projects
  for update to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());
create policy "projects: admin delete" on public.projects
  for delete to authenticated using (app.is_admin());

-- Project members: visible to anyone who can see the project; managers+ manage.
create policy "members: read if project visible" on public.project_members
  for select to authenticated using (app.can_view_project(project_id));
create policy "members: manager insert" on public.project_members
  for insert to authenticated with check (app.is_manager_or_above());
create policy "members: manager delete" on public.project_members
  for delete to authenticated using (app.is_manager_or_above());

-- Status labels, custom columns, groups, milestones: read if visible, managers+ write.
create policy "labels: read" on public.status_labels
  for select to authenticated using (app.can_view_project(project_id));
create policy "labels: manager write" on public.status_labels
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

create policy "columns: read" on public.project_columns
  for select to authenticated using (app.can_view_project(project_id));
create policy "columns: manager write" on public.project_columns
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

create policy "groups: read" on public.groups
  for select to authenticated using (app.can_view_project(project_id));
create policy "groups: manager write" on public.groups
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

create policy "milestones: read" on public.milestones
  for select to authenticated using (app.can_view_project(project_id));
create policy "milestones: manager write" on public.milestones
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

-- Tasks: read if visible; create/update if editor (technicians on assigned projects);
-- delete managers+ only.
create policy "tasks: read" on public.tasks
  for select to authenticated using (app.can_view_project(project_id));
create policy "tasks: editor insert" on public.tasks
  for insert to authenticated with check (app.can_edit_project(project_id));
create policy "tasks: editor update" on public.tasks
  for update to authenticated using (app.can_edit_project(project_id)) with check (app.can_edit_project(project_id));
create policy "tasks: manager delete" on public.tasks
  for delete to authenticated using (app.is_manager_or_above());

-- Assignees: managers+ assign anyone; technicians may (un)assign themselves on tasks they can edit.
create policy "assignees: read" on public.task_assignees
  for select to authenticated using (app.can_view_project(app.task_project(task_id)));
create policy "assignees: manager insert" on public.task_assignees
  for insert to authenticated with check (
    app.is_manager_or_above()
    or (user_id = auth.uid() and app.can_edit_project(app.task_project(task_id)))
  );
create policy "assignees: manager delete" on public.task_assignees
  for delete to authenticated using (
    app.is_manager_or_above()
    or (user_id = auth.uid() and app.can_edit_project(app.task_project(task_id)))
  );

-- Dependencies: Gantt planning is a manager job.
create policy "deps: read" on public.task_dependencies
  for select to authenticated using (app.can_view_project(app.task_project(task_id)));
create policy "deps: manager write" on public.task_dependencies
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

-- Checklist: editors.
create policy "checklist: read" on public.task_checklist_items
  for select to authenticated using (app.can_view_project(app.task_project(task_id)));
create policy "checklist: editor write" on public.task_checklist_items
  for all to authenticated
  using (app.can_edit_project(app.task_project(task_id)))
  with check (app.can_edit_project(app.task_project(task_id)));

-- Comments: editors post as themselves; authors edit/delete own; admins delete any.
create policy "comments: read" on public.comments
  for select to authenticated using (app.can_view_project(app.task_project(task_id)));
create policy "comments: editor insert" on public.comments
  for insert to authenticated with check (
    author_id = auth.uid() and app.can_edit_project(app.task_project(task_id))
  );
create policy "comments: author update" on public.comments
  for update to authenticated using (author_id = auth.uid())
  with check (author_id = auth.uid() and app.can_edit_project(app.task_project(task_id)));
create policy "comments: author or admin delete" on public.comments
  for delete to authenticated using (author_id = auth.uid() or app.is_admin());

-- Attachments: editors upload; uploader or managers+ delete.
create policy "attachments: read" on public.attachments
  for select to authenticated using (app.can_view_project(app.task_project(task_id)));
create policy "attachments: editor insert" on public.attachments
  for insert to authenticated with check (
    uploaded_by = auth.uid() and app.can_edit_project(app.task_project(task_id))
  );
create policy "attachments: uploader or manager delete" on public.attachments
  for delete to authenticated using (uploaded_by = auth.uid() or app.is_manager_or_above());

-- Activity log: read-only for viewers (rows are inserted by triggers).
create policy "activity: read" on public.activity_log
  for select to authenticated using (app.can_view_project(project_id));

-- Share links: managers+ only. Clients use the token via a function, not this table.
create policy "share links: manager all" on public.share_links
  for all to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());

grant execute on all functions in schema app to anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261119000003_daily_updates.sql
-- =====================================================================
-- Orion Projects — 0003 Daily work updates (site diary) and photos
-- =====================================================================

create table public.daily_updates (
  id         uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  author_id  uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  work_date  date not null default (now() at time zone 'Europe/Malta')::date,
  work_done  text not null check (char_length(work_done) between 1 and 8000),
  hours      numeric(4, 1) check (hours is null or (hours >= 0 and hours <= 24)),
  issues     text check (char_length(issues) <= 4000),
  -- Client-generated id so offline-queued updates are idempotent when re-sent.
  client_ref uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index daily_updates_project_date_idx on public.daily_updates (project_id, work_date desc, created_at desc);
create index daily_updates_author_date_idx on public.daily_updates (author_id, work_date desc);
create trigger daily_updates_touch before update on public.daily_updates
  for each row execute function app.touch_updated_at();

create table public.daily_update_photos (
  id              uuid primary key default gen_random_uuid(),
  daily_update_id uuid not null references public.daily_updates (id) on delete cascade,
  project_id      uuid not null references public.projects (id) on delete cascade,
  storage_path    text not null unique,
  width           integer,
  height          integer,
  size_bytes      bigint,
  caption         text check (char_length(caption) <= 500),
  uploaded_by     uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at      timestamptz not null default now()
);
create index daily_photos_update_idx on public.daily_update_photos (daily_update_id);
create index daily_photos_project_idx on public.daily_update_photos (project_id, created_at desc);

create or replace function app.photo_project_consistency()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.daily_updates d
                 where d.id = new.daily_update_id and d.project_id = new.project_id) then
    raise exception 'Photo project must match its daily update';
  end if;
  return new;
end;
$$;
create trigger daily_photos_consistency before insert or update on public.daily_update_photos
  for each row execute function app.photo_project_consistency();

-- Author may edit/delete their own update for 24 hours after posting.
create or replace function app.can_modify_daily_update(p_update uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.daily_updates d
    where d.id = p_update
      and (
        app.is_manager_or_above()
        or (d.author_id = auth.uid()
            and d.created_at > now() - interval '24 hours'
            and app.can_edit_project(d.project_id))
      )
  )
$$;

alter table public.daily_updates       enable row level security;
alter table public.daily_update_photos enable row level security;

create policy "daily: read" on public.daily_updates
  for select to authenticated using (app.can_view_project(project_id));
create policy "daily: editor insert own" on public.daily_updates
  for insert to authenticated with check (author_id = auth.uid() and app.can_edit_project(project_id));
create policy "daily: author (24h) or manager update" on public.daily_updates
  for update to authenticated using (app.can_modify_daily_update(id))
  with check (app.can_edit_project(project_id));
create policy "daily: author (24h) or manager delete" on public.daily_updates
  for delete to authenticated using (app.can_modify_daily_update(id));

create policy "photos: read" on public.daily_update_photos
  for select to authenticated using (app.can_view_project(project_id));
create policy "photos: insert on modifiable update" on public.daily_update_photos
  for insert to authenticated with check (
    uploaded_by = auth.uid() and app.can_modify_daily_update(daily_update_id)
  );
create policy "photos: delete on modifiable update" on public.daily_update_photos
  for delete to authenticated using (app.can_modify_daily_update(daily_update_id));

grant execute on all functions in schema app to anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261119000004_chat.sql
-- =====================================================================
-- Orion Projects — 0004 Chat: project, management and general channels
-- =====================================================================

create type public.channel_type as enum ('project', 'management', 'general');

create table public.channels (
  id          uuid primary key default gen_random_uuid(),
  type        public.channel_type not null,
  project_id  uuid unique references public.projects (id) on delete cascade,
  name        text not null check (char_length(name) between 1 and 80),
  description text check (char_length(description) <= 500),
  archived    boolean not null default false,
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  check ((type = 'project') = (project_id is not null))
);

-- Per-user channel state: last read (for unread badges) and mute.
-- Access is NOT granted by this table; it is derived from the channel type.
create table public.channel_members (
  channel_id   uuid not null references public.channels (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  last_read_at timestamptz not null default now(),
  muted        boolean not null default false,
  primary key (channel_id, user_id)
);

create table public.messages (
  id         uuid primary key default gen_random_uuid(),
  channel_id uuid not null references public.channels (id) on delete cascade,
  author_id  uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  parent_id  uuid references public.messages (id) on delete cascade,   -- reply thread
  task_id    uuid references public.tasks (id) on delete set null,      -- task link chip
  body       text not null default '' check (char_length(body) <= 8000),
  mentions   uuid[] not null default '{}',
  edited_at  timestamptz,
  deleted_at timestamptz,
  created_at timestamptz not null default now()
);
create index messages_channel_created_idx on public.messages (channel_id, created_at desc);
create index messages_parent_idx on public.messages (parent_id) where parent_id is not null;

create table public.message_attachments (
  id           uuid primary key default gen_random_uuid(),
  message_id   uuid not null references public.messages (id) on delete cascade,
  storage_path text not null,
  file_name    text not null check (char_length(file_name) <= 255),
  mime_type    text,
  size_bytes   bigint,
  width        integer,
  height       integer,
  created_at   timestamptz not null default now()
);
create index message_attachments_message_idx on public.message_attachments (message_id);

create table public.message_reactions (
  message_id uuid not null references public.messages (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  emoji      text not null check (char_length(emoji) between 1 and 16),
  created_at timestamptz not null default now(),
  primary key (message_id, user_id, emoji)
);

-- ---------------------------------------------------------------------
-- Channel permission helpers
-- ---------------------------------------------------------------------
create or replace function app.can_view_channel(p_channel uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select case c.type
      when 'general'    then app.is_active()
      when 'management' then app.is_manager_or_above()
      when 'project'    then app.can_view_project(c.project_id)
    end
    from public.channels c where c.id = p_channel
  ), false)
$$;

create or replace function app.can_post_channel(p_channel uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce((
    select case c.type
      when 'general'    then app.is_manager_or_above()       -- announcements
      when 'management' then app.is_manager_or_above()
      when 'project'    then app.can_edit_project(c.project_id)
        or (app.current_role() = 'basic'
            and app.is_project_member(c.project_id)
            and (select s.basic_can_post_chat from public.app_settings s where s.id))
    end
    from public.channels c where c.id = p_channel and not c.archived
  ), false)
$$;

create or replace function app.message_channel(p_message uuid)
returns uuid
language sql stable security definer
set search_path = ''
as $$ select channel_id from public.messages where id = p_message $$;

-- Every new project gets its own chat channel.
create or replace function app.create_project_channel()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if not new.is_template then
    insert into public.channels (type, project_id, name, created_by)
    values ('project', new.id, new.name, auth.uid());
  end if;
  return new;
end;
$$;
create trigger projects_create_channel after insert on public.projects
  for each row execute function app.create_project_channel();

-- Keep project channel name in sync.
create or replace function app.rename_project_channel()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if new.name is distinct from old.name then
    update public.channels set name = new.name where project_id = new.id;
  end if;
  return new;
end;
$$;
create trigger projects_rename_channel after update of name on public.projects
  for each row execute function app.rename_project_channel();

-- Default company-wide channels.
insert into public.channels (type, name, description) values
  ('general', 'General & Announcements', 'Company-wide news. Everyone can read; managers post.'),
  ('management', 'Management', 'Private channel for administrators and managers.');

-- =====================================================================
-- Row Level Security
-- =====================================================================
alter table public.channels            enable row level security;
alter table public.channel_members     enable row level security;
alter table public.messages            enable row level security;
alter table public.message_attachments enable row level security;
alter table public.message_reactions   enable row level security;

create policy "channels: read if allowed" on public.channels
  for select to authenticated using (app.can_view_channel(id));
-- Managers+ create/edit management & general channels. Project channels are created by trigger.
create policy "channels: manager insert" on public.channels
  for insert to authenticated with check (app.is_manager_or_above() and type <> 'project');
create policy "channels: manager update" on public.channels
  for update to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());
create policy "channels: admin delete" on public.channels
  for delete to authenticated using (app.is_admin() and type <> 'project');

create policy "channel state: own" on public.channel_members
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and app.can_view_channel(channel_id));

create policy "messages: read if channel visible" on public.messages
  for select to authenticated using (app.can_view_channel(channel_id));
create policy "messages: post if allowed" on public.messages
  for insert to authenticated with check (author_id = auth.uid() and app.can_post_channel(channel_id));
create policy "messages: author edits own" on public.messages
  for update to authenticated using (author_id = auth.uid())
  with check (author_id = auth.uid() and app.can_post_channel(channel_id));
create policy "messages: author or admin delete" on public.messages
  for delete to authenticated using (author_id = auth.uid() or app.is_admin());

create policy "msg attachments: read" on public.message_attachments
  for select to authenticated using (app.can_view_channel(app.message_channel(message_id)));
create policy "msg attachments: author insert" on public.message_attachments
  for insert to authenticated with check (
    exists (select 1 from public.messages m where m.id = message_id and m.author_id = auth.uid())
  );
create policy "msg attachments: author or admin delete" on public.message_attachments
  for delete to authenticated using (
    app.is_admin() or exists (select 1 from public.messages m where m.id = message_id and m.author_id = auth.uid())
  );

create policy "reactions: read" on public.message_reactions
  for select to authenticated using (app.can_view_channel(app.message_channel(message_id)));
create policy "reactions: add own if can post" on public.message_reactions
  for insert to authenticated with check (
    user_id = auth.uid() and app.can_post_channel(app.message_channel(message_id))
  );
create policy "reactions: remove own" on public.message_reactions
  for delete to authenticated using (user_id = auth.uid());

-- Realtime (live chat). Guarded so the migration also runs on plain Postgres in tests.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.messages, public.message_reactions;
  end if;
end $$;

grant execute on all functions in schema app to anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261119000005_notifications.sql
-- =====================================================================
-- Orion Projects — 0005 Notifications, preferences, web push subscriptions
-- (Rows are created by triggers / server jobs in phase 6.)
-- =====================================================================

create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  type       text not null,  -- task.assigned | mention | task.status | task.due_soon | daily.new | ...
  title      text not null check (char_length(title) <= 200),
  body       text check (char_length(body) <= 1000),
  link       text check (char_length(link) <= 500),
  project_id uuid references public.projects (id) on delete cascade,
  task_id    uuid references public.tasks (id) on delete cascade,
  actor_id   uuid references public.profiles (id) on delete set null,
  read_at    timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);
create index notifications_unread_idx on public.notifications (user_id) where read_at is null;

create table public.notification_preferences (
  user_id          uuid primary key references public.profiles (id) on delete cascade default auth.uid(),
  push_enabled     boolean not null default true,
  email_digest     boolean not null default false,
  -- Per-type switches, e.g. {"task.assigned": true, "daily.new": false}. Missing = on.
  types            jsonb not null default '{}'::jsonb,
  quiet_hours_from time,
  quiet_hours_to   time,
  updated_at       timestamptz not null default now()
);
create trigger notification_prefs_touch before update on public.notification_preferences
  for each row execute function app.touch_updated_at();

create table public.push_subscriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  endpoint   text not null unique,
  p256dh     text not null,
  auth       text not null,
  user_agent text,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
create index push_subscriptions_user_idx on public.push_subscriptions (user_id);

alter table public.notifications            enable row level security;
alter table public.notification_preferences enable row level security;
alter table public.push_subscriptions       enable row level security;

-- Users only ever see and manage their own notifications. No insert policy:
-- notifications are created by SECURITY DEFINER triggers / the server.
create policy "notifications: read own" on public.notifications
  for select to authenticated using (user_id = auth.uid());
create policy "notifications: mark own read" on public.notifications
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "notifications: delete own" on public.notifications
  for delete to authenticated using (user_id = auth.uid());

create policy "prefs: own" on public.notification_preferences
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy "push: own" on public.push_subscriptions
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and app.is_active());

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.notifications;
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261119000006_storage.sql
-- =====================================================================
-- Orion Projects — 0006 Storage buckets (all PRIVATE) and access policies
-- Files are served to the browser via short-lived signed URLs.
--
-- Path conventions (first folder decides access):
--   avatars/<user_id>/<file>
--   project-files/<project_id>/tasks/<task_id>/<file>
--   project-files/<project_id>/daily/<daily_update_id>/<file>
--   chat-files/<channel_id>/<message_id>/<file>
--   branding/clients/<client_id>/<file>
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('avatars',       'avatars',       false, 5242880,  array['image/jpeg','image/png','image/webp']),
  ('project-files', 'project-files', false, 26214400, null),
  ('chat-files',    'chat-files',    false, 26214400, null),
  ('branding',      'branding',      false, 2097152,  array['image/jpeg','image/png','image/webp','image/svg+xml'])
on conflict (id) do nothing;

create or replace function app.try_uuid(p text)
returns uuid
language plpgsql immutable
set search_path = ''
as $$
begin
  return p::uuid;
exception when others then
  return null;
end;
$$;

create or replace function app.path_folder(p_name text, p_index integer)
returns text
language sql immutable
set search_path = ''
as $$ select (string_to_array(p_name, '/'))[p_index] $$;

-- Avatars: any active user can view (signed URL); you manage only your own folder.
create policy "avatars: active read" on storage.objects
  for select to authenticated
  using (bucket_id = 'avatars' and (app.is_active() or app.path_folder(name, 1) = auth.uid()::text));
create policy "avatars: own insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'avatars' and app.path_folder(name, 1) = auth.uid()::text);
create policy "avatars: own update" on storage.objects
  for update to authenticated
  using (bucket_id = 'avatars' and app.path_folder(name, 1) = auth.uid()::text)
  with check (bucket_id = 'avatars' and app.path_folder(name, 1) = auth.uid()::text);
create policy "avatars: own delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'avatars' and app.path_folder(name, 1) = auth.uid()::text);

-- Project files: same rules as the project itself.
create policy "project files: read" on storage.objects
  for select to authenticated
  using (bucket_id = 'project-files' and app.can_view_project(app.try_uuid(app.path_folder(name, 1))));
create policy "project files: editor upload" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'project-files' and app.can_edit_project(app.try_uuid(app.path_folder(name, 1))));
create policy "project files: uploader or manager delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'project-files'
         and app.can_view_project(app.try_uuid(app.path_folder(name, 1)))
         and (owner_id = auth.uid()::text or app.is_manager_or_above()));

-- Chat files: channel rules.
create policy "chat files: read" on storage.objects
  for select to authenticated
  using (bucket_id = 'chat-files' and app.can_view_channel(app.try_uuid(app.path_folder(name, 1))));
create policy "chat files: poster upload" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'chat-files' and app.can_post_channel(app.try_uuid(app.path_folder(name, 1))));
create policy "chat files: uploader or admin delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'chat-files' and (owner_id = auth.uid()::text or app.is_admin()));

-- Branding (client logos): active users read, managers+ write.
create policy "branding: active read" on storage.objects
  for select to authenticated using (bucket_id = 'branding' and app.is_active());
create policy "branding: manager insert" on storage.objects
  for insert to authenticated with check (bucket_id = 'branding' and app.is_manager_or_above());
create policy "branding: manager update" on storage.objects
  for update to authenticated using (bucket_id = 'branding' and app.is_manager_or_above())
  with check (bucket_id = 'branding' and app.is_manager_or_above());
create policy "branding: manager delete" on storage.objects
  for delete to authenticated using (bucket_id = 'branding' and app.is_manager_or_above());

grant execute on all functions in schema app to anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261120000007_table_grants.sql
-- =====================================================================
-- Orion Projects — 0007 Explicit table privileges
--
-- Newer Supabase projects no longer grant the API roles access to new tables
-- automatically ("permission denied for table …"). Grant them explicitly.
-- This does NOT weaken security: Row Level Security policies (0001–0006)
-- still decide which rows each user can see or change.
-- =====================================================================

grant usage on schema public to anon, authenticated, service_role;

-- Signed-in users: table access, filtered row-by-row by RLS.
grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to authenticated;

-- The server (secret key) has full access; it bypasses RLS by design.
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;

-- Anonymous visitors get no table access at all. Public client share links
-- (phase 3) go through a dedicated SECURITY DEFINER function instead.
revoke all on all tables in schema public from anon;

-- Rate-limit counters are for the server only.
revoke all on public.rate_limits from authenticated;

-- Keep the same behaviour for tables added by future migrations.
alter default privileges in schema public grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public grant usage, select on sequences to authenticated;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261120000008_boards.sql
-- =====================================================================
-- Orion Projects — 0008 Phase 2: boards, My Tasks, task details, templates
--
-- Read functions are SECURITY INVOKER: they run with the caller's rights,
-- so Row Level Security decides what comes back (a Technician asking for a
-- project they are not on simply gets NULL).
-- =====================================================================

-- Built-in board columns a manager has hidden for a project
-- (status, owners, priority, start_date, due_date, progress, dependencies).
alter table public.projects add column if not exists hidden_columns text[] not null default '{}';

-- ---------------------------------------------------------------------
-- Whole board in one round trip
-- ---------------------------------------------------------------------
create or replace function public.get_project_board(p_project uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'project', to_jsonb(p) || jsonb_build_object(
      'client', (select jsonb_build_object('id', c.id, 'name', c.name) from public.clients c where c.id = p.client_id)
    ),
    'labels', coalesce((select jsonb_agg(to_jsonb(s) order by s.position) from public.status_labels s where s.project_id = p.id), '[]'),
    'columns', coalesce((select jsonb_agg(to_jsonb(pc) order by pc.position) from public.project_columns pc where pc.project_id = p.id), '[]'),
    'groups', coalesce((select jsonb_agg(to_jsonb(g) order by g.position, g.created_at) from public.groups g where g.project_id = p.id), '[]'),
    'tasks', coalesce((
      select jsonb_agg(
        to_jsonb(t) - 'internal_notes' - 'description' || jsonb_build_object(
          'has_description', t.description is not null and t.description <> '',
          'assignees', coalesce((select jsonb_agg(a.user_id order by a.assigned_at) from public.task_assignees a where a.task_id = t.id), '[]'),
          'blocked_by', coalesce((select jsonb_agg(d.depends_on_task_id) from public.task_dependencies d where d.task_id = t.id), '[]'),
          'checklist_total', (select count(*) from public.task_checklist_items ci where ci.task_id = t.id),
          'checklist_done', (select count(*) from public.task_checklist_items ci where ci.task_id = t.id and ci.is_done),
          'comment_count', (select count(*) from public.comments cm where cm.task_id = t.id),
          'attachment_count', (select count(*) from public.attachments at where at.task_id = t.id)
        ) order by t.position, t.created_at)
      from public.tasks t where t.project_id = p.id
    ), '[]'),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', m.user_id, 'first_name', pr.first_name, 'last_name', pr.last_name,
        'email', pr.email, 'avatar_url', pr.avatar_url, 'role', pr.role
      ) order by pr.first_name, pr.last_name)
      from public.project_members m join public.profiles pr on pr.id = m.user_id
      where m.project_id = p.id
    ), '[]'),
    'milestones', coalesce((select jsonb_agg(to_jsonb(ms) order by ms.date) from public.milestones ms where ms.project_id = p.id), '[]')
  )
  from public.projects p
  where p.id = p_project
$$;

-- ---------------------------------------------------------------------
-- Projects list with progress numbers
-- ---------------------------------------------------------------------
create or replace function public.list_projects(p_include_archived boolean default false, p_templates boolean default false)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(item order by (item->>'name')), '[]')
  from (
    select to_jsonb(p) || jsonb_build_object(
      'client', (select jsonb_build_object('id', c.id, 'name', c.name) from public.clients c where c.id = p.client_id),
      'task_count', (select count(*) from public.tasks t where t.project_id = p.id),
      'done_count', (select count(*) from public.tasks t where t.project_id = p.id and t.completed_at is not null),
      'overdue_count', (select count(*) from public.tasks t where t.project_id = p.id and t.completed_at is null
                          and t.due_date < (now() at time zone 'Europe/Malta')::date),
      'avg_progress', (select coalesce(round(avg(t.progress)), 0) from public.tasks t where t.project_id = p.id),
      'member_ids', coalesce((select jsonb_agg(m.user_id) from public.project_members m where m.project_id = p.id), '[]')
    ) as item
    from public.projects p
    where p.is_template = p_templates
      and (p_include_archived or p.status <> 'archived')
  ) x
$$;

-- ---------------------------------------------------------------------
-- My Tasks: everything assigned to me across projects
-- (open tasks + anything finished in the last 7 days)
-- ---------------------------------------------------------------------
create or replace function public.get_my_tasks()
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', t.id, 'title', t.title, 'project_id', t.project_id, 'group_id', t.group_id,
      'status_id', t.status_id, 'priority', t.priority, 'start_date', t.start_date,
      'due_date', t.due_date, 'progress', t.progress, 'completed_at', t.completed_at,
      'project', jsonb_build_object('name', p.name, 'color', p.color),
      'status', case when s.id is null then null else jsonb_build_object('name', s.name, 'color', s.color, 'is_done', s.is_done) end,
      'group', jsonb_build_object('name', g.name)
    ) order by t.due_date nulls last, t.position
  ), '[]')
  from public.tasks t
  join public.task_assignees a on a.task_id = t.id and a.user_id = auth.uid()
  join public.projects p on p.id = t.project_id
  join public.groups g on g.id = t.group_id
  left join public.status_labels s on s.id = t.status_id
  where p.is_template = false
    and p.status <> 'archived'
    and (t.completed_at is null or t.completed_at > now() - interval '7 days')
$$;

-- ---------------------------------------------------------------------
-- Everything the task drawer shows
-- ---------------------------------------------------------------------
create or replace function public.get_task_detail(p_task uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'task', to_jsonb(t) || jsonb_build_object(
      'assignees', coalesce((select jsonb_agg(a.user_id) from public.task_assignees a where a.task_id = t.id), '[]')
    ),
    'checklist', coalesce((select jsonb_agg(to_jsonb(ci) order by ci.position, ci.created_at)
                            from public.task_checklist_items ci where ci.task_id = t.id), '[]'),
    'comments', coalesce((
      select jsonb_agg(to_jsonb(cm) || jsonb_build_object(
        'author', jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url)
      ) order by cm.created_at)
      from public.comments cm left join public.profiles pr on pr.id = cm.author_id
      where cm.task_id = t.id
    ), '[]'),
    'attachments', coalesce((
      select jsonb_agg(to_jsonb(at) order by at.created_at desc) from public.attachments at where at.task_id = t.id
    ), '[]'),
    'blocked_by', coalesce((
      select jsonb_agg(jsonb_build_object('id', o.id, 'title', o.title, 'due_date', o.due_date, 'completed_at', o.completed_at))
      from public.task_dependencies d join public.tasks o on o.id = d.depends_on_task_id
      where d.task_id = t.id
    ), '[]'),
    'blocking', coalesce((
      select jsonb_agg(jsonb_build_object('id', o.id, 'title', o.title))
      from public.task_dependencies d join public.tasks o on o.id = d.task_id
      where d.depends_on_task_id = t.id
    ), '[]'),
    'activity', coalesce((
      select jsonb_agg(x order by x->>'created_at' desc) from (
        select to_jsonb(al) || jsonb_build_object(
          'actor', jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email)
        ) as x
        from public.activity_log al left join public.profiles pr on pr.id = al.actor_id
        where al.task_id = t.id
        order by al.created_at desc
        limit 50
      ) recent
    ), '[]')
  )
  from public.tasks t
  where t.id = p_task
$$;

-- ---------------------------------------------------------------------
-- Duplicate a project's structure (templates). Runs as the caller, so only
-- managers/admins succeed (RLS on every insert). Copies status labels,
-- custom columns, groups, tasks (dates shifted to the new start date),
-- checklists and dependencies. Not copied: people, comments, files, chat.
-- ---------------------------------------------------------------------
create or replace function public.duplicate_project(
  p_source uuid,
  p_name text,
  p_as_template boolean default false,
  p_start_date date default null,
  p_client_id uuid default null
)
returns uuid
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  src public.projects%rowtype;
  new_id uuid;
  shift integer := 0;
  group_map jsonb := '{}';
  task_map jsonb := '{}';
  r record;
  nid uuid;
begin
  if not app.is_manager_or_above() then
    raise exception 'Only managers can create projects' using errcode = '42501';
  end if;
  select * into src from public.projects where id = p_source;
  if not found then
    raise exception 'Project not found';
  end if;
  if p_start_date is not null and src.start_date is not null then
    shift := p_start_date - src.start_date;
  end if;

  insert into public.projects (name, code, description, client_id, status, start_date, end_date, color, is_template, hidden_columns)
  values (p_name, null, src.description, coalesce(p_client_id, src.client_id), 'active',
          coalesce(p_start_date, src.start_date), src.end_date + shift, src.color, p_as_template, src.hidden_columns)
  returning id into new_id;

  -- Replace the default labels with the source project's labels.
  delete from public.status_labels where project_id = new_id;
  for r in select * from public.status_labels where project_id = p_source order by position loop
    insert into public.status_labels (project_id, name, color, position, is_done)
    values (new_id, r.name, r.color, r.position, r.is_done);
  end loop;

  insert into public.project_columns (project_id, name, kind, position)
  select new_id, name, kind, position from public.project_columns where project_id = p_source;

  for r in select * from public.groups where project_id = p_source order by position loop
    insert into public.groups (project_id, name, color, position)
    values (new_id, r.name, r.color, r.position) returning id into nid;
    group_map := group_map || jsonb_build_object(r.id::text, nid);
  end loop;

  for r in select * from public.tasks where project_id = p_source order by position loop
    insert into public.tasks (project_id, group_id, title, description, status_id, priority,
                              start_date, due_date, progress, position, custom_values)
    values (new_id, (group_map->>r.group_id::text)::uuid, r.title, r.description,
            -- New copies start at the first ("not started") label, not the source's progress.
            (select s.id from public.status_labels s where s.project_id = new_id order by s.position limit 1),
            r.priority, r.start_date + shift, r.due_date + shift, 0, r.position, r.custom_values)
    returning id into nid;
    task_map := task_map || jsonb_build_object(r.id::text, nid);

    insert into public.task_checklist_items (task_id, title, is_done, position)
    select nid, title, false, position from public.task_checklist_items where task_id = r.id;
  end loop;

  insert into public.task_dependencies (task_id, depends_on_task_id)
  select (task_map->>d.task_id::text)::uuid, (task_map->>d.depends_on_task_id::text)::uuid
  from public.task_dependencies d
  join public.tasks t on t.id = d.task_id
  where t.project_id = p_source;

  insert into public.milestones (project_id, title, description, date, color)
  select new_id, title, description, date + shift, color from public.milestones where project_id = p_source;

  return new_id;
end;
$$;

-- Function privileges: callable by signed-in users only (RLS applies inside).
revoke all on function public.get_project_board(uuid) from public, anon;
revoke all on function public.list_projects(boolean, boolean) from public, anon;
revoke all on function public.get_my_tasks() from public, anon;
revoke all on function public.get_task_detail(uuid) from public, anon;
revoke all on function public.duplicate_project(uuid, text, boolean, date, uuid) from public, anon;
grant execute on function public.get_project_board(uuid) to authenticated;
grant execute on function public.list_projects(boolean, boolean) to authenticated;
grant execute on function public.get_my_tasks() to authenticated;
grant execute on function public.get_task_detail(uuid) to authenticated;
grant execute on function public.duplicate_project(uuid, text, boolean, date, uuid) to authenticated;

-- Live board updates (Realtime respects RLS for each subscriber).
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['tasks', 'groups', 'task_assignees', 'status_labels', 'task_dependencies'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261121000009_share_links.sql
-- =====================================================================
-- Orion Projects — 0009 Phase 3: read-only client share links
--
-- Clients open /share/<token> without logging in. They never touch the
-- tables directly: this SECURITY DEFINER function checks the token
-- (exists, not revoked, not expired) and returns ONLY what a client should
-- see — no internal notes, no comments, no files, and owners only if the
-- link allows it.
-- =====================================================================

create or replace function public.get_shared_project(p_token text)
returns jsonb
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  link public.share_links%rowtype;
  result jsonb;
begin
  if p_token is null or length(p_token) < 32 or length(p_token) > 128 then
    return null;
  end if;

  select * into link from public.share_links
  where token = p_token
    and revoked_at is null
    and (expires_at is null or expires_at > now());
  if not found then
    return null;
  end if;

  update public.share_links set last_viewed_at = now() where id = link.id;

  select jsonb_build_object(
    'link', jsonb_build_object('label', link.label, 'expires_at', link.expires_at, 'hide_owners', link.hide_owners),
    'project', jsonb_build_object(
      'id', p.id, 'name', p.name, 'code', p.code, 'color', p.color,
      'start_date', p.start_date, 'end_date', p.end_date, 'status', p.status,
      'client', (select jsonb_build_object('name', c.name, 'logo_path', c.logo_path) from public.clients c where c.id = p.client_id)
    ),
    'labels', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'color', s.color, 'is_done', s.is_done) order by s.position)
                        from public.status_labels s where s.project_id = p.id), '[]'),
    'groups', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name, 'color', g.color) order by g.position, g.created_at)
                        from public.groups g where g.project_id = p.id), '[]'),
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id, 'group_id', t.group_id, 'title', t.title, 'status_id', t.status_id,
        'start_date', t.start_date, 'due_date', t.due_date, 'progress', t.progress,
        'completed_at', t.completed_at,
        'blocked_by', coalesce((select jsonb_agg(d.depends_on_task_id) from public.task_dependencies d where d.task_id = t.id), '[]'),
        'owners', case when link.hide_owners then '[]'::jsonb else coalesce((
          select jsonb_agg(trim(pr.first_name || ' ' || pr.last_name))
          from public.task_assignees a join public.profiles pr on pr.id = a.user_id
          where a.task_id = t.id), '[]') end
      ) order by t.position, t.created_at)
      from public.tasks t where t.project_id = p.id
    ), '[]'),
    'milestones', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'title', m.title, 'date', m.date, 'color', m.color) order by m.date)
                            from public.milestones m where m.project_id = p.id), '[]'),
    'generated_at', now()
  )
  into result
  from public.projects p
  where p.id = link.project_id;

  return result;
end;
$$;

revoke all on function public.get_shared_project(text) from public;
grant execute on function public.get_shared_project(text) to anon, authenticated, service_role;

-- Milestones and share links show up live on open boards too.
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['milestones'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261121000010_daily_diary.sql
-- =====================================================================
-- Orion Projects — 0010 Phase 4: daily site diary feed, photo gallery and
-- the managers' "who has posted today" overview.
--
-- All functions are SECURITY INVOKER: Row Level Security decides which
-- projects' updates and photos each person can see.
-- Photos are stored twice: <id>.jpg (≈1600px) and <id>_thumb.jpg (≈480px).
-- =====================================================================

create index if not exists daily_updates_feed_idx on public.daily_updates (work_date desc, created_at desc);

-- Feed of daily updates, newest day first. Keyset pagination with
-- (p_before_date, p_before_created) taken from the last item of the previous page.
create or replace function public.get_daily_feed(
  p_project uuid default null,
  p_from date default null,
  p_to date default null,
  p_author uuid default null,
  p_before_date date default null,
  p_before_created timestamptz default null,
  p_limit integer default 20
)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(item order by (item->>'work_date') desc, (item->>'created_at') desc), '[]')
  from (
    select jsonb_build_object(
      'id', d.id, 'project_id', d.project_id, 'author_id', d.author_id, 'work_date', d.work_date,
      'work_done', d.work_done, 'hours', d.hours, 'issues', d.issues,
      'created_at', d.created_at, 'updated_at', d.updated_at,
      'project', jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color),
      'author', jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url),
      'photos', coalesce((
        select jsonb_agg(jsonb_build_object('id', ph.id, 'storage_path', ph.storage_path, 'width', ph.width, 'height', ph.height, 'caption', ph.caption)
                         order by ph.created_at)
        from public.daily_update_photos ph where ph.daily_update_id = d.id
      ), '[]')
    ) as item
    from public.daily_updates d
    join public.projects p on p.id = d.project_id
    left join public.profiles pr on pr.id = d.author_id
    where (p_project is null or d.project_id = p_project)
      and (p_author is null or d.author_id = p_author)
      and (p_from is null or d.work_date >= p_from)
      and (p_to is null or d.work_date <= p_to)
      and (p_before_date is null or (d.work_date, d.created_at) < (p_before_date, p_before_created))
    order by d.work_date desc, d.created_at desc
    limit least(greatest(coalesce(p_limit, 20), 1), 500)
  ) x
$$;

-- Photo gallery for one project, newest first, optional date range.
create or replace function public.get_project_photos(
  p_project uuid,
  p_from date default null,
  p_to date default null,
  p_before_created timestamptz default null,
  p_limit integer default 60
)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(item order by (item->>'created_at') desc), '[]')
  from (
    select jsonb_build_object(
      'id', ph.id, 'storage_path', ph.storage_path, 'width', ph.width, 'height', ph.height, 'caption', ph.caption,
      'created_at', ph.created_at, 'work_date', d.work_date, 'daily_update_id', d.id,
      'author', jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email)
    ) as item
    from public.daily_update_photos ph
    join public.daily_updates d on d.id = ph.daily_update_id
    left join public.profiles pr on pr.id = d.author_id
    where ph.project_id = p_project
      and (p_from is null or d.work_date >= p_from)
      and (p_to is null or d.work_date <= p_to)
      and (p_before_created is null or ph.created_at < p_before_created)
    order by ph.created_at desc
    limit least(greatest(coalesce(p_limit, 60), 1), 200)
  ) x
$$;

-- Managers: for each active project, which technicians on it have posted on a given day.
create or replace function public.get_daily_status(p_date date)
returns jsonb
language plpgsql stable security invoker
set search_path = ''
as $$
begin
  if not app.is_manager_or_above() then
    return null;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'project', jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color),
      'update_count', (select count(*) from public.daily_updates d where d.project_id = p.id and d.work_date = p_date),
      'people', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url,
          'posted', exists (select 1 from public.daily_updates d where d.project_id = p.id and d.author_id = pr.id and d.work_date = p_date)
        ) order by pr.first_name, pr.last_name)
        from public.project_members m
        join public.profiles pr on pr.id = m.user_id
        where m.project_id = p.id and pr.role = 'technician' and pr.status = 'active'
      ), '[]')
    ) order by p.name)
    from public.projects p
    where p.status = 'active' and not p.is_template
  ), '[]');
end;
$$;

-- Projects the current user can post a daily update for (Daily Update form).
create or replace function public.get_postable_projects()
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color) order by p.name), '[]')
  from public.projects p
  where p.status = 'active' and not p.is_template and app.can_edit_project(p.id)
    and (app.is_manager_or_above() or app.is_project_member(p.id))
$$;

revoke all on function public.get_daily_feed(uuid, date, date, uuid, date, timestamptz, integer) from public, anon;
revoke all on function public.get_project_photos(uuid, date, date, timestamptz, integer) from public, anon;
revoke all on function public.get_daily_status(date) from public, anon;
revoke all on function public.get_postable_projects() from public, anon;
grant execute on function public.get_daily_feed(uuid, date, date, uuid, date, timestamptz, integer) to authenticated;
grant execute on function public.get_project_photos(uuid, date, date, timestamptz, integer) to authenticated;
grant execute on function public.get_daily_status(date) to authenticated;
grant execute on function public.get_postable_projects() to authenticated;

do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['daily_updates', 'daily_update_photos'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261122000011_chat.sql
-- =====================================================================
-- Orion Projects — 0011 Phase 5: chat reading functions & unread counts
--
-- Channel access rules already exist (0004): who can see/post is decided by
-- app.can_view_channel / app.can_post_channel. These functions run as the
-- caller (SECURITY INVOKER), so they only ever return what RLS allows.
-- Unread = messages from other people after the user's last_read_at
-- (or after they joined, if they never opened the channel).
-- =====================================================================

create index if not exists messages_channel_top_idx on public.messages (channel_id, created_at desc) where parent_id is null;

create or replace function app.my_last_read(p_channel uuid)
returns timestamptz
language sql stable security definer
set search_path = ''
as $$
  select coalesce(
    (select cm.last_read_at from public.channel_members cm where cm.channel_id = p_channel and cm.user_id = auth.uid()),
    (select coalesce(pr.approved_at, pr.created_at) from public.profiles pr where pr.id = auth.uid())
  )
$$;

-- Channels I can see, with last message preview, unread count and whether I may post.
create or replace function public.list_my_channels()
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(item order by (item->>'sort_key') desc), '[]')
  from (
    select jsonb_build_object(
      'id', c.id, 'type', c.type, 'name', c.name, 'description', c.description, 'project_id', c.project_id,
      'archived', c.archived,
      'project_color', (select p.color from public.projects p where p.id = c.project_id),
      'can_post', app.can_post_channel(c.id),
      'muted', coalesce((select cm.muted from public.channel_members cm where cm.channel_id = c.id and cm.user_id = auth.uid()), false),
      'unread', (select count(*) from public.messages m
                 where m.channel_id = c.id and m.author_id <> auth.uid() and m.deleted_at is null
                   and m.created_at > app.my_last_read(c.id)),
      'last', (select jsonb_build_object('body', left(m.body, 140), 'created_at', m.created_at, 'deleted', m.deleted_at is not null,
                                         'has_attachments', exists (select 1 from public.message_attachments a where a.message_id = m.id),
                                         'author', trim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')))
               from public.messages m left join public.profiles pr on pr.id = m.author_id
               where m.channel_id = c.id order by m.created_at desc limit 1),
      'sort_key', coalesce((select max(m.created_at) from public.messages m where m.channel_id = c.id), c.created_at)
    ) as item
    from public.channels c
    where not c.archived
  ) x
$$;

-- Total unread for the badge on the Chats tab (muted channels don't count).
create or replace function public.get_unread_total()
returns integer
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(sum((
    select count(*) from public.messages m
    where m.channel_id = c.id and m.author_id <> auth.uid() and m.deleted_at is null
      and m.created_at > app.my_last_read(c.id)
  )), 0)::integer
  from public.channels c
  where not c.archived
    and not coalesce((select cm.muted from public.channel_members cm where cm.channel_id = c.id and cm.user_id = auth.uid()), false)
$$;

-- One message as the app shows it (author, attachments, reactions, reply count, linked task).
create or replace function app.message_json(m public.messages)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'id', m.id, 'channel_id', m.channel_id, 'author_id', m.author_id, 'parent_id', m.parent_id,
    'body', case when m.deleted_at is null then m.body else '' end,
    'mentions', m.mentions, 'created_at', m.created_at, 'edited_at', m.edited_at, 'deleted', m.deleted_at is not null,
    'author', (select jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url)
               from public.profiles pr where pr.id = m.author_id),
    'attachments', case when m.deleted_at is not null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'storage_path', a.storage_path, 'file_name', a.file_name, 'mime_type', a.mime_type,
                                          'size_bytes', a.size_bytes, 'width', a.width, 'height', a.height) order by a.created_at)
      from public.message_attachments a where a.message_id = m.id), '[]') end,
    'reactions', coalesce((
      select jsonb_agg(jsonb_build_object('emoji', r.emoji, 'count', r.n, 'mine', r.mine, 'names', r.names) order by r.first_at)
      from (
        select mr.emoji, count(*) as n, bool_or(mr.user_id = auth.uid()) as mine, min(mr.created_at) as first_at,
               jsonb_agg(trim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, ''))) as names
        from public.message_reactions mr left join public.profiles pr on pr.id = mr.user_id
        where mr.message_id = m.id group by mr.emoji
      ) r), '[]'),
    'reply_count', (select count(*) from public.messages rp where rp.parent_id = m.id and rp.deleted_at is null),
    'last_reply_at', (select max(rp.created_at) from public.messages rp where rp.parent_id = m.id),
    'task', (select jsonb_build_object('id', t.id, 'title', t.title, 'project_id', t.project_id, 'completed', t.completed_at is not null)
             from public.tasks t where t.id = m.task_id)
  )
$$;

-- Top-level messages of a channel, newest page first (returned oldest → newest).
create or replace function public.get_channel_messages(p_channel uuid, p_before timestamptz default null, p_limit integer default 40)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(app.message_json(m) order by m.created_at), '[]')
  from (
    select * from public.messages
    where channel_id = p_channel and parent_id is null
      and (p_before is null or created_at < p_before)
    order by created_at desc
    limit least(greatest(coalesce(p_limit, 40), 1), 100)
  ) m
$$;

-- Messages newer than a moment (live updates catch-up), including replies.
create or replace function public.get_channel_messages_since(p_channel uuid, p_since timestamptz)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(app.message_json(m) order by m.created_at), '[]')
  from public.messages m
  where m.channel_id = p_channel and m.created_at > p_since
  limit 200
$$;

-- A single message (after an edit, delete or reaction).
create or replace function public.get_message(p_message uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select app.message_json(m) from public.messages m where m.id = p_message
$$;

-- A thread: the parent message and all its replies.
create or replace function public.get_thread(p_parent uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'parent', (select app.message_json(m) from public.messages m where m.id = p_parent),
    'replies', coalesce((select jsonb_agg(app.message_json(m) order by m.created_at) from public.messages m where m.parent_id = p_parent), '[]')
  )
  where exists (select 1 from public.messages m where m.id = p_parent)
$$;

-- People who can read a channel (for @mentions).
create or replace function public.get_channel_people(p_channel uuid)
returns jsonb
language plpgsql stable security invoker
set search_path = ''
as $$
declare c public.channels%rowtype;
begin
  select * into c from public.channels where id = p_channel;
  if not found then return null; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('user_id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url)
                     order by pr.first_name, pr.last_name)
    from public.profiles pr
    where pr.status = 'active'
      and case c.type
            when 'general' then true
            when 'management' then pr.role in ('admin', 'manager')
            when 'project' then pr.role in ('admin', 'manager')
                             or exists (select 1 from public.project_members m where m.project_id = c.project_id and m.user_id = pr.id)
          end
  ), '[]');
end;
$$;

-- Sends a message and its attachments in ONE transaction (others never see a
-- photo message without its photos). Runs as the caller: RLS checks that they
-- may post in the channel and that the attachments belong to their message.
create or replace function public.send_chat_message(
  p_id uuid,
  p_channel uuid,
  p_body text,
  p_parent uuid default null,
  p_task uuid default null,
  p_mentions uuid[] default '{}',
  p_attachments jsonb default '[]'
)
returns jsonb
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  m public.messages%rowtype;
  bad integer;
begin
  if coalesce(trim(p_body), '') = '' and jsonb_array_length(coalesce(p_attachments, '[]')) = 0 then
    raise exception 'Write a message or add a file';
  end if;
  if p_parent is not null and not exists (select 1 from public.messages x where x.id = p_parent and x.channel_id = p_channel and x.parent_id is null) then
    raise exception 'You can only reply to a message in the same chat';
  end if;
  select count(*) into bad from jsonb_array_elements(coalesce(p_attachments, '[]')) a
  where (a->>'storage_path') not like p_channel::text || '/' || p_id::text || '/%';
  if bad > 0 then
    raise exception 'Invalid attachment';
  end if;

  insert into public.messages (id, channel_id, author_id, parent_id, task_id, body, mentions)
  values (p_id, p_channel, auth.uid(), p_parent, p_task, coalesce(trim(p_body), ''), coalesce(p_mentions, '{}'))
  returning * into m;

  insert into public.message_attachments (id, message_id, storage_path, file_name, mime_type, size_bytes, width, height)
  select x.id, m.id, x.storage_path, left(x.file_name, 255), x.mime_type, x.size_bytes, x.width, x.height
  from jsonb_to_recordset(coalesce(p_attachments, '[]'))
    as x(id uuid, storage_path text, file_name text, mime_type text, size_bytes bigint, width integer, height integer);

  return app.message_json(m);
end;
$$;

-- Mark a channel as read now.
create or replace function public.mark_channel_read(p_channel uuid)
returns void
language sql volatile security invoker
set search_path = ''
as $$
  insert into public.channel_members (channel_id, user_id, last_read_at)
  values (p_channel, auth.uid(), now())
  on conflict (channel_id, user_id) do update set last_read_at = excluded.last_read_at
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'list_my_channels()', 'get_unread_total()', 'get_channel_messages(uuid, timestamptz, integer)',
    'get_channel_messages_since(uuid, timestamptz)', 'get_message(uuid)', 'get_thread(uuid)',
    'get_channel_people(uuid)', 'mark_channel_read(uuid)',
    'send_chat_message(uuid, uuid, text, uuid, uuid, uuid[], jsonb)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
grant execute on all functions in schema app to anon, authenticated, service_role;

-- Live updates for edits and attachments too (messages & reactions were added in 0004).
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['messages', 'message_reactions', 'message_attachments'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261123000012_notifications_health.sql
-- =====================================================================
-- Orion Projects — 0012 Phase 6: notifications, delay warnings (health)
--
-- Notifications are created by triggers when something happens (assigned,
-- mentioned, status changed, comment, new daily update) and by the daily job
-- (due soon / overdue). The app then sends a phone push for new rows
-- (pushed_at is null) and an optional daily email summary.
--
-- The delay rules below are mirrored exactly in src/lib/health.ts (and both
-- are tested). Keep them in sync.
-- =====================================================================

alter table public.notifications add column if not exists pushed_at timestamptz;
create index if not exists notifications_push_queue_idx on public.notifications (created_at) where pushed_at is null;

-- ---------------------------------------------------------------------
-- Delay / health rules
--   red   : overdue, or waiting for a task that is itself overdue
--   amber : due within 2 days with < 50 % progress
--           OR behind schedule (progress < time elapsed % − 30)
--           OR waiting for an unfinished task and due to start within 3 days
-- ---------------------------------------------------------------------
create or replace function app.task_risk(t public.tasks, p_today date)
returns jsonb
language plpgsql stable security invoker
set search_path = ''
as $$
declare
  late_blocker text;
  open_blocker text;
  elapsed numeric;
begin
  if t.completed_at is not null then
    return null;
  end if;
  if t.due_date is not null and t.due_date < p_today then
    return jsonb_build_object('level', 'red', 'reason', 'Overdue');
  end if;
  select b.title into late_blocker
  from public.task_dependencies d join public.tasks b on b.id = d.depends_on_task_id
  where d.task_id = t.id and b.completed_at is null and b.due_date is not null and b.due_date < p_today
  limit 1;
  if late_blocker is not null then
    return jsonb_build_object('level', 'red', 'reason', 'Waiting for a late task: ' || late_blocker);
  end if;
  if t.due_date is not null and t.due_date <= p_today + 2 and t.progress < 50 then
    return jsonb_build_object('level', 'amber', 'reason', 'Due soon with little progress');
  end if;
  if t.start_date is not null and t.due_date is not null and t.due_date > t.start_date and p_today > t.start_date then
    elapsed := least(100, (p_today - t.start_date)::numeric * 100 / (t.due_date - t.start_date));
    if t.progress < elapsed - 30 then
      return jsonb_build_object('level', 'amber', 'reason', 'Behind schedule');
    end if;
  end if;
  select b.title into open_blocker
  from public.task_dependencies d join public.tasks b on b.id = d.depends_on_task_id
  where d.task_id = t.id and b.completed_at is null
  limit 1;
  if open_blocker is not null and coalesce(t.start_date, t.due_date) is not null and coalesce(t.start_date, t.due_date) <= p_today + 3 then
    return jsonb_build_object('level', 'amber', 'reason', 'Waiting for: ' || open_blocker);
  end if;
  return null;
end;
$$;

-- Project health from its tasks:
--   red   : any red high/critical task, or ≥ 2 red tasks and ≥ 20 % of open tasks red,
--           or the planned end date has passed with work still open
--   amber : any red or amber task
--   green : otherwise
create or replace function app.project_health(p_project uuid, p_today date)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  with risks as (
    select t.priority, app.task_risk(t, p_today) as r
    from public.tasks t where t.project_id = p_project and t.completed_at is null
  ), c as (
    select count(*) as open_count,
           count(*) filter (where r->>'level' = 'red') as red,
           count(*) filter (where r->>'level' = 'red' and priority in ('high', 'critical')) as red_important,
           count(*) filter (where r->>'level' = 'amber') as amber
    from risks
  )
  select jsonb_build_object(
    'level', case
      when c.red_important > 0 or (c.red >= 2 and c.red * 5 >= c.open_count)
        or (p.end_date is not null and p.end_date < p_today and c.open_count > 0) then 'red'
      when c.red > 0 or c.amber > 0 then 'amber'
      else 'green' end,
    'red', c.red, 'amber', c.amber, 'open', c.open_count,
    'past_end', p.end_date is not null and p.end_date < p_today and c.open_count > 0
  )
  from c, public.projects p where p.id = p_project
$$;

create or replace function public.malta_today()
returns date
language sql stable
set search_path = ''
as $$ select (now() at time zone 'Europe/Malta')::date $$;

-- list_projects now includes the health badge.
create or replace function public.list_projects(p_include_archived boolean default false, p_templates boolean default false)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(item order by (item->>'name')), '[]')
  from (
    select to_jsonb(p) || jsonb_build_object(
      'client', (select jsonb_build_object('id', c.id, 'name', c.name) from public.clients c where c.id = p.client_id),
      'task_count', (select count(*) from public.tasks t where t.project_id = p.id),
      'done_count', (select count(*) from public.tasks t where t.project_id = p.id and t.completed_at is not null),
      'overdue_count', (select count(*) from public.tasks t where t.project_id = p.id and t.completed_at is null
                          and t.due_date < public.malta_today()),
      'avg_progress', (select coalesce(round(avg(t.progress)), 0) from public.tasks t where t.project_id = p.id),
      'member_ids', coalesce((select jsonb_agg(m.user_id) from public.project_members m where m.project_id = p.id), '[]'),
      'health', case when p.is_template or p.status <> 'active' then null else app.project_health(p.id, public.malta_today()) end
    ) as item
    from public.projects p
    where p.is_template = p_templates
      and (p_include_archived or p.status <> 'archived')
  ) x
$$;

-- ---------------------------------------------------------------------
-- Creating notifications
-- ---------------------------------------------------------------------
-- Respects each person's settings: a type switched off (types->>type = 'false') is skipped.
create or replace function app.notify(
  p_user uuid, p_type text, p_title text, p_body text, p_link text,
  p_project uuid default null, p_task uuid default null, p_actor uuid default auth.uid()
)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  if p_user is null or p_user is not distinct from p_actor then
    return;
  end if;
  if not exists (select 1 from public.profiles where id = p_user and status = 'active') then
    return;
  end if;
  if exists (select 1 from public.notification_preferences np where np.user_id = p_user and (np.types ->> p_type) = 'false') then
    return;
  end if;
  insert into public.notifications (user_id, type, title, body, link, project_id, task_id, actor_id)
  values (p_user, p_type, left(p_title, 200), left(p_body, 1000), left(p_link, 500), p_project, p_task, p_actor);
end;
$$;

create or replace function app.person_name(p_user uuid)
returns text
language sql stable security definer
set search_path = ''
as $$
  select coalesce(nullif(trim(first_name || ' ' || last_name), ''), email::text, 'Someone') from public.profiles where id = p_user
$$;

-- Assigned to a task
create or replace function app.on_task_assigned()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare t public.tasks%rowtype;
begin
  select * into t from public.tasks where id = new.task_id;
  perform app.notify(new.user_id, 'task.assigned',
    app.person_name(coalesce(new.assigned_by, auth.uid())) || ' assigned you a task',
    t.title, '/projects/' || t.project_id || '/board?task=' || t.id, t.project_id, t.id, coalesce(auth.uid(), new.assigned_by));
  return new;
end;
$$;
drop trigger if exists task_assignees_notify on public.task_assignees;
create trigger task_assignees_notify after insert on public.task_assignees
  for each row execute function app.on_task_assigned();

-- Status changed → everyone assigned (except whoever changed it)
create or replace function app.on_task_status()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  label text;
  a record;
begin
  if new.status_id is not distinct from old.status_id then
    return new;
  end if;
  select name into label from public.status_labels where id = new.status_id;
  for a in select user_id from public.task_assignees where task_id = new.id loop
    perform app.notify(a.user_id, 'task.status',
      app.person_name(auth.uid()) || ' changed the status to “' || coalesce(label, 'none') || '”',
      new.title, '/projects/' || new.project_id || '/board?task=' || new.id, new.project_id, new.id);
  end loop;
  return new;
end;
$$;
drop trigger if exists tasks_status_notify on public.tasks;
create trigger tasks_status_notify after update of status_id on public.tasks
  for each row execute function app.on_task_status();

-- Comment on a task → assignees and earlier commenters
create or replace function app.on_task_comment()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.tasks%rowtype;
  u uuid;
begin
  select * into t from public.tasks where id = new.task_id;
  for u in
    select user_id from public.task_assignees where task_id = new.task_id
    union select author_id from public.comments where task_id = new.task_id and id <> new.id
  loop
    perform app.notify(u, 'task.comment', app.person_name(new.author_id) || ' commented on “' || t.title || '”',
      left(new.body, 200), '/projects/' || t.project_id || '/board?task=' || t.id, t.project_id, t.id, new.author_id);
  end loop;
  return new;
end;
$$;
drop trigger if exists comments_notify on public.comments;
create trigger comments_notify after insert on public.comments
  for each row execute function app.on_task_comment();

-- @mentions in chat (only people who can read that chat are stored as mentions)
create or replace function app.on_message_mentions()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.channels%rowtype;
  u uuid;
begin
  if coalesce(array_length(new.mentions, 1), 0) = 0 then
    return new;
  end if;
  select * into c from public.channels where id = new.channel_id;
  foreach u in array new.mentions loop
    perform app.notify(u, 'mention', app.person_name(new.author_id) || ' mentioned you in ' || c.name,
      left(new.body, 200), '/chats/' || c.id, c.project_id, null, new.author_id);
  end loop;
  return new;
end;
$$;
drop trigger if exists messages_mentions_notify on public.messages;
create trigger messages_mentions_notify after insert on public.messages
  for each row execute function app.on_message_mentions();

-- New daily update → managers who are on that project
create or replace function app.on_daily_update()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  p public.projects%rowtype;
  u uuid;
begin
  select * into p from public.projects where id = new.project_id;
  for u in
    select m.user_id from public.project_members m join public.profiles pr on pr.id = m.user_id
    where m.project_id = new.project_id and pr.role in ('admin', 'manager')
  loop
    perform app.notify(u, 'daily.new', app.person_name(new.author_id) || ' posted a daily update · ' || p.name,
      left(new.work_done, 200), '/projects/' || p.id || '/diary', p.id, null, new.author_id);
  end loop;
  return new;
end;
$$;
drop trigger if exists daily_updates_notify on public.daily_updates;
create trigger daily_updates_notify after insert on public.daily_updates
  for each row execute function app.on_daily_update();

-- ---------------------------------------------------------------------
-- Daily job (called by the server's cron with the secret key)
-- ---------------------------------------------------------------------
-- "Due today", "due tomorrow" and "overdue" reminders for assignees — at most one
-- of each per task per person per day.
create or replace function public.create_due_notifications()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  today date := public.malta_today();
  r record;
  n integer := 0;
  kind text;
  title text;
begin
  for r in
    select t.id, t.title, t.project_id, t.due_date, a.user_id
    from public.tasks t
    join public.task_assignees a on a.task_id = t.id
    join public.projects p on p.id = t.project_id
    where t.completed_at is null and p.status = 'active' and not p.is_template
      and t.due_date is not null and t.due_date <= today + 1
      and t.due_date >= today - 1   -- remind about "overdue" once, the day after it was due
  loop
    kind := case when r.due_date < today then 'task.overdue' else 'task.due_soon' end;
    title := case when r.due_date < today then 'Overdue: ' when r.due_date = today then 'Due today: ' else 'Due tomorrow: ' end || r.title;
    if not exists (
      select 1 from public.notifications x
      where x.user_id = r.user_id and x.task_id = r.id and x.type = kind and x.created_at > now() - interval '20 hours'
    ) then
      perform app.notify(r.user_id, kind, title, null, '/projects/' || r.project_id || '/board?task=' || r.id, r.project_id, r.id, null);
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;

-- Hands out notifications that still need a phone push, marking them so two
-- servers never send the same one twice.
create or replace function public.claim_push_batch(p_limit integer default 200)
returns setof public.notifications
language sql volatile security definer
set search_path = ''
as $$
  update public.notifications set pushed_at = now()
  where id in (
    select id from public.notifications
    where pushed_at is null and created_at > now() - interval '1 day'
    order by created_at
    limit p_limit
    for update skip locked
  )
  returning *
$$;

-- People who want the daily email summary, with what to tell them.
create or replace function public.get_digest_recipients()
returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', pr.id, 'email', pr.email, 'first_name', pr.first_name,
    'notifications', coalesce((
      select jsonb_agg(jsonb_build_object('title', n.title, 'body', n.body, 'link', n.link, 'created_at', n.created_at) order by n.created_at desc)
      from (select * from public.notifications n where n.user_id = pr.id and n.read_at is null and n.created_at > now() - interval '24 hours'
            order by n.created_at desc limit 30) n
    ), '[]'),
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object('title', t.title, 'due_date', t.due_date, 'project', p.name,
                                          'link', '/projects/' || t.project_id || '/board?task=' || t.id) order by t.due_date)
      from public.tasks t join public.task_assignees a on a.task_id = t.id and a.user_id = pr.id
      join public.projects p on p.id = t.project_id
      where t.completed_at is null and p.status = 'active' and t.due_date <= public.malta_today() + 1
    ), '[]')
  )), '[]')
  from public.profiles pr
  join public.notification_preferences np on np.user_id = pr.id and np.email_digest
  where pr.status = 'active'
$$;

-- Housekeeping: old read notifications and rate-limit counters.
create or replace function public.cleanup_old_data()
returns void
language sql volatile security definer
set search_path = ''
as $$
  delete from public.notifications where created_at < now() - interval '90 days';
  delete from public.rate_limits where window_start < now() - interval '2 days';
$$;

revoke all on function public.create_due_notifications() from public, anon, authenticated;
revoke all on function public.claim_push_batch(integer) from public, anon, authenticated;
revoke all on function public.get_digest_recipients() from public, anon, authenticated;
revoke all on function public.cleanup_old_data() from public, anon, authenticated;
grant execute on function public.create_due_notifications() to service_role;
grant execute on function public.claim_push_batch(integer) to service_role;
grant execute on function public.get_digest_recipients() to service_role;
grant execute on function public.cleanup_old_data() to service_role;
grant execute on function public.malta_today() to authenticated, service_role;
grant execute on all functions in schema app to anon, authenticated, service_role;


